import { readFileSync } from 'node:fs';
import { dirname, join } from 'node:path';
import { fileURLToPath } from 'node:url';
import { describe, expect, it } from 'vitest';
import { readIcnsTypes } from './icns.mjs';
import { readIcoSizes } from './ico.mjs';
import { ICNS_FRAMES } from './icon-frames.mjs';

// Guards the COMMITTED artwork binaries, not the packers (scripts/ico.test.mjs and
// scripts/icns.test.mjs cover those). assets/icon.ico, assets/icon.icns and assets/icon.png are
// generated by `yarn icons` and checked in, so nothing in a normal build regenerates them — a
// hand-edit, a bad merge, or a run of build-icons.mjs that silently dropped a frame would ship a
// blurry or missing icon and no other test would notice.

const ASSETS = join(dirname(fileURLToPath(import.meta.url)), '..', 'assets');

/** Every size Windows picks between, smallest first — must match FRAMES in icon-frames.mjs. */
const EXPECTED_SIZES = [16, 24, 32, 48, 64, 128, 256];

/** A PNG's IHDR carries its real dimensions at a fixed offset; bytes 0..8 are the signature. */
function pngSize(buffer, at = 0) {
  return { width: buffer.readUInt32BE(at + 16), height: buffer.readUInt32BE(at + 20) };
}

describe('the committed app icon', () => {
  const ico = readFileSync(join(ASSETS, 'icon.ico'));

  it('carries every frame size the build pipeline is supposed to produce', () => {
    expect(readIcoSizes(ico)).toEqual(EXPECTED_SIZES);
  });

  // A directory entry that advertises 48 while pointing at a 64px payload is legal ICO and loads
  // fine — Windows just scales it, badly. Only reading the payload catches that.
  it('has payloads whose real pixel dimensions match the sizes the directory advertises', () => {
    readIcoSizes(ico).forEach((size, index) => {
      const entry = 6 + index * 16;
      const offset = ico.readUInt32LE(entry + 12);
      expect(pngSize(ico, offset)).toEqual({ width: size, height: size });
    });
  });

  it('is a PNG at 512px for the Linux packagers, which want one large raster', () => {
    expect(pngSize(readFileSync(join(ASSETS, 'icon.png')))).toEqual({ width: 512, height: 512 });
  });
});

describe('the macOS frame table', () => {
  // ICNS has an OSType for exactly these pixel sizes (scripts/icns.mjs), and 1024 is the largest
  // Finder and the Dock ever ask for — no 24 or 48 here, unlike the ICO table.
  it('covers every ICNS size, up to the 1024px Retina 512pt', () => {
    expect(ICNS_FRAMES.map((f) => f.size)).toEqual([16, 32, 64, 128, 256, 512, 1024]);
  });

  // The same 32px crossover as the ICO table: below it the detailed mark's A closes up.
  it('draws only the 16px frame from the small-size artwork', () => {
    expect(ICNS_FRAMES.filter((f) => f.source === 'icon-small.svg').map((f) => f.size)).toEqual([
      16,
    ]);
    expect(ICNS_FRAMES.filter((f) => f.size >= 32).every((f) => f.source === 'icon.svg')).toBe(
      true,
    );
  });
});

describe('the committed macOS icon', () => {
  const icns = readFileSync(join(ASSETS, 'icon.icns'));

  // 32, 256 and 512 appear twice: once as their own 1x type, once as the @2x of half their size.
  // 64 has no 1x slot ('icp6' is 48px), so it appears only as 'ic12', the 32pt@2x.
  it('carries an entry for every frame, plus the three Retina duplicates', () => {
    expect(readIcnsTypes(icns)).toEqual([
      'icp4',
      'icp5',
      'ic11',
      'ic12',
      'ic07',
      'ic08',
      'ic13',
      'ic09',
      'ic14',
      'ic10',
    ]);
  });

  it('has PNG payloads whose real pixel dimensions match their OSType', () => {
    const sizeForType = {
      icp4: 16,
      icp5: 32,
      ic11: 32,
      ic12: 64,
      ic07: 128,
      ic08: 256,
      ic13: 256,
      ic09: 512,
      ic14: 512,
      ic10: 1024,
    };
    for (let offset = 8; offset < icns.length; offset += icns.readUInt32BE(offset + 4)) {
      const size = sizeForType[icns.toString('latin1', offset, offset + 4)];
      expect(pngSize(icns, offset + 8)).toEqual({ width: size, height: size });
    }
  });
});
